<?php
declare(strict_types=1);
namespace EPejabat\Modules\EForms;
use EPejabat\Core\{Authorization,Core,Database,Crypto,Audit,Notifications,Documents,Pdf,Accounts};
final class Service {
 public static function permit(\PDO $p,int $u,string $action,int $org):void {if(!Database::query($p,'SELECT 1 FROM users WHERE id=? AND is_active=1',[$u])->fetchColumn())throw new \RuntimeException('Login aktif diperlukan.');if(Authorization::super($p,$u))return;if(in_array($action,['submissions.create','documents.upload'],true)){$own=Database::query($p,'SELECT s.organisation_id FROM staff_profiles s JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE u.id=?',[$u])->fetchColumn();if($own&&Authorization::allowed($p,$u,'eforms.'.$action,(int)$own)&&Database::query($p,'SELECT 1 FROM organisation_hierarchy WHERE ancestor_id=? AND descendant_id=?',[$org,$own])->fetchColumn())return;}if(!Authorization::allowed($p,$u,'eforms.'.$action,$org))throw new \RuntimeException('Akses e-Forms di luar permission/skop.');}
 public static function template(\PDO $p,int $u,int $org,string $title,array $fields,array $steps,bool $self,string $ack,?int $id=null,bool $visual=false):int {self::permit($p,$u,'templates.manage',$org);$fields=Schema::definition($fields);$title=Core::text($title);$ack=Core::text($ack,1000);if(!$steps||count($steps)>5)throw new \InvalidArgumentException('1–5 langkah semakan diperlukan.');$normalized=[];foreach($steps as $i=>$s){$reviewer=Core::id($s['user_id']??null);self::permit($p,$reviewer,'submissions.review',$org);$kind=$s['kind']??'approve';if(!in_array($kind,['review','approve'],true)||($i===count($steps)-1&&$kind!=='approve'))throw new \InvalidArgumentException('Langkah akhir mesti kelulusan.');$normalized[]=['user_id'=>$reviewer,'kind'=>$kind,'label'=>Core::text(($s['label']??'')?:($kind==='review'?'Penyemak':'Pelulus'),100)];}return Core::tx($p,function()use($p,$u,$org,$title,$fields,$normalized,$self,$ack,$id,$visual){if($id){$old=Database::query($p,'SELECT * FROM eforms_templates WHERE id=? FOR UPDATE',[$id])->fetch();if(!$visual&&Visual::ready($p)&&Database::query($p,'SELECT 1 FROM eforms_visual_versions vv JOIN eforms_versions v ON v.id=vv.version_id WHERE v.template_id=?',[$id])->fetchColumn())throw new \RuntimeException('Gunakan Smart Form Studio untuk template PDF.');if(!$old||(int)$old['organisation_id']!==$org)throw new \RuntimeException('Organisasi borang tidak boleh diubah.');Database::query($p,"UPDATE eforms_templates SET title=?,status='draft' WHERE id=?",[$title,$id]);}else{Database::query($p,'INSERT INTO eforms_templates(organisation_id,title,created_by) VALUES(?,?,?)',[$org,$title,$u]);$id=(int)$p->lastInsertId();}$n=(int)Database::query($p,'SELECT COALESCE(MAX(version),0)+1 FROM eforms_versions WHERE template_id=?',[$id])->fetchColumn();$json=json_encode($fields,JSON_THROW_ON_ERROR);$flow=json_encode($normalized,JSON_THROW_ON_ERROR);Database::query($p,'INSERT INTO eforms_versions(template_id,version,schema_json,workflow_json,allow_self_approval,acknowledgement,checksum,created_by) VALUES(?,?,?,?,?,?,?,?)',[$id,$n,$json,$flow,$self?1:0,$ack,hash('sha256',$json.$flow.($self?'1':'0').$ack),$u]);Audit::record($p,'eforms.template_version_created',$u,$org,(string)$id,'eforms',null,null,['version'=>$n]);return $id;});}
 public static function publish(\PDO $p,int $u,int $id,bool $active=true):void {Core::tx($p,function()use($p,$u,$id,$active){$r=Database::query($p,'SELECT * FROM eforms_templates WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r)throw new \RuntimeException('Borang tidak wujud.');self::permit($p,$u,'templates.manage',(int)$r['organisation_id']);if($active&&Visual::ready($p))Visual::publishCheck($p,$id);Database::query($p,'UPDATE eforms_templates SET status=? WHERE id=?',[$active?'published':'inactive',$id]);Audit::record($p,'eforms.template_status',$u,(int)$r['organisation_id'],(string)$id,'eforms',null,null,['status'=>$active?'published':'inactive']);});}
 public static function draft(\PDO $p,int $u,int $form):int {Core::module($p,'eforms');return Core::tx($p,function()use($p,$u,$form){$t=Database::query($p,"SELECT * FROM eforms_templates WHERE id=? AND status='published' FOR UPDATE",[$form])->fetch();if(!$t)throw new \RuntimeException('Borang belum diterbitkan.');self::permit($p,$u,'submissions.create',(int)$t['organisation_id']);$v=Database::query($p,'SELECT id FROM eforms_versions WHERE template_id=? ORDER BY version DESC LIMIT 1',[$form])->fetchColumn();if(Visual::ready($p)){$b=Visual::binding($p,(int)$v);if($b&&($b['definition']['effective_date']??'')>gmdate('Y-m-d'))throw new \RuntimeException('Borang belum berkuat kuasa.');}Database::query($p,'INSERT INTO eforms_submissions(version_id,organisation_id,applicant_id,payload_cipher) VALUES(?,?,?,?)',[$v,$t['organisation_id'],$u,Crypto::seal('{}')]);$id=(int)$p->lastInsertId();self::event($p,$u,$id,(int)$t['organisation_id'],'draft_created','');return $id;});}
 public static function get(\PDO $p,int $u,int $id,bool $lock=false):array {Core::module($p,'eforms');$r=Database::query($p,'SELECT s.*,v.schema_json,v.workflow_json,v.allow_self_approval,v.acknowledgement,v.checksum,v.version,t.title,t.id AS template_id FROM eforms_submissions s JOIN eforms_versions v ON v.id=s.version_id JOIN eforms_templates t ON t.id=v.template_id WHERE s.id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$r)throw new \RuntimeException('Permohonan tidak wujud.');$steps=json_decode($r['workflow_json'],true,512,JSON_THROW_ON_ERROR);$originalSteps=$steps;if(Visual::ready($p)){foreach(Database::query($p,'SELECT step_index,delegated_to FROM eforms_delegations WHERE submission_id=? ORDER BY id',[$id])->fetchAll() as $de){if(isset($steps[(int)$de['step_index']]))$steps[(int)$de['step_index']]['user_id']=(int)$de['delegated_to'];}}$assigned=in_array($u,array_column($steps,'user_id'),true);if((int)$r['applicant_id']===$u)self::permit($p,$u,'submissions.create',(int)$r['organisation_id']);elseif($assigned&&$r['status']!=='draft')self::permit($p,$u,'submissions.review',(int)$r['organisation_id']);else self::permit($p,$u,'submissions.manage',(int)$r['organisation_id']);$expected=hash('sha256',$r['schema_json'].$r['workflow_json'].$r['allow_self_approval'].$r['acknowledgement']);if(!hash_equals($r['checksum'],$expected))throw new \RuntimeException('Integriti versi borang gagal.');$r['fields']=json_decode($r['schema_json'],true,512,JSON_THROW_ON_ERROR);$r['steps']=$steps;$r['values']=json_decode(Crypto::open($r['payload_cipher']),true,512,JSON_THROW_ON_ERROR);$r['files']=Database::query($p,'SELECT a.field_key,a.document_id FROM eforms_attachments a WHERE submission_id=?',[$id])->fetchAll();return $r;}
 private static function event(\PDO $p,int $u,int $id,int $org,string $action,string $reason):void {Database::query($p,'INSERT INTO eforms_history(submission_id,actor_id,action,reason) VALUES(?,?,?,?)',[$id,$u,$action,$reason?:null]);Audit::record($p,'eforms.'.$action,$u,$org,(string)$id,'eforms',$reason?:null);}
 private static function notify(\PDO $p,array $r,string $status):void {$to=[(int)$r['applicant_id']];if($status==='submitted')$to[]=(int)$r['steps'][(int)$r['step_index']]['user_id'];foreach(array_unique($to) as $u){$email=Database::query($p,'SELECT email FROM users WHERE id=? AND is_active=1',[$u])->fetchColumn();if(!$email)continue;Notifications::inApp($p,$u,'e-Forms #'.$r['id'],$status,'eforms');Notifications::enqueue($p,$email,'eforms_status',['submission'=>(string)$r['id'],'status'=>$status,'url'=>Accounts::origin().'/eforms?submission='.$r['id']]);}}
 public static function save(\PDO $p,int $u,int $id,array $raw,int $revision,bool $submit=false,bool $ack=false):void {Core::tx($p,function()use($p,$u,$id,$raw,$revision,$submit,$ack){$r=self::get($p,$u,$id,true);if((int)$r['applicant_id']!==$u||!in_array($r['status'],['draft','returned'],true)||(int)$r['revision']!==$revision)throw new \RuntimeException('Permohonan dikunci atau telah berubah.');if($submit&&!$ack)throw new \InvalidArgumentException('Perakuan digital diperlukan.');$files=array_column($r['files'],'document_id','field_key');$values=Schema::values($p,$r['fields'],$raw,(int)$r['organisation_id'],$submit,$files);if($submit){foreach($r['steps'] as $step){self::permit($p,(int)$step['user_id'],'submissions.review',(int)$r['organisation_id']);if(!$r['allow_self_approval']&&(int)$step['user_id']===$u)throw new \RuntimeException('Workflow melarang self-approval; Admin mesti menukar pelulus pada versi baharu.');}}$status=$submit?'submitted':$r['status'];Database::query($p,'UPDATE eforms_submissions SET payload_cipher=?,status=?,step_index=?,revision=revision+1,submitted_at=?,acknowledged_at=?,acknowledgement_hash=? WHERE id=?',[Crypto::seal(json_encode($values,JSON_THROW_ON_ERROR)),$status,$submit?0:$r['step_index'],$submit?gmdate('Y-m-d H:i:s'):$r['submitted_at'],$submit?gmdate('Y-m-d H:i:s'):$r['acknowledged_at'],$submit?hash('sha256',$r['acknowledgement']):$r['acknowledgement_hash'],$id]);self::event($p,$u,$id,(int)$r['organisation_id'],$submit?'submitted':'draft_saved','');if($submit){if(Visual::ready($p))Visual::capturePrint($p,$id,$u,false);$r['step_index']=0;self::notify($p,$r,'submitted');}});}
 public static function decide(\PDO $p,int $u,int $id,string $decision,string $reason,int $revision):void {$reason=Core::text($reason,500);if(!in_array($decision,['approve','reject','return'],true))throw new \InvalidArgumentException('Keputusan tidak sah.');Core::tx($p,function()use($p,$u,$id,$decision,$reason,$revision){$r=self::get($p,$u,$id,true);$step=$r['steps'][(int)$r['step_index']]??null;if($r['status']!=='submitted'||(int)$r['revision']!==$revision||!$step||(int)$step['user_id']!==$u)throw new \RuntimeException('Bukan giliran semakan anda.');self::permit($p,$u,'submissions.review',(int)$r['organisation_id']);if(!$r['allow_self_approval']&&(int)$r['applicant_id']===$u)throw new \RuntimeException('Self-approval ditolak.');$next=(int)$r['step_index'];$status=match($decision){'reject'=>'rejected','return'=>'returned',default=>++$next>=count($r['steps'])?'approved':'submitted'};Database::query($p,'UPDATE eforms_submissions SET status=?,step_index=?,revision=revision+1 WHERE id=?',[$status,$next,$id]);self::event($p,$u,$id,(int)$r['organisation_id'],$decision,$reason);if($decision==='approve'&&Visual::ready($p))Visual::capturePrint($p,$id,$u,$status==='approved',(int)$r['step_index']+1);$r['step_index']=$next;self::notify($p,$r,$status);});}
 public static function attachment(\PDO $p,int $u,int $id,string $key,array $file,int $revision):int {return Core::tx($p,function()use($p,$u,$id,$key,$file,$revision){$r=self::get($p,$u,$id,true);if((int)$r['applicant_id']!==$u||!in_array($r['status'],['draft','returned'],true)||(int)$r['revision']!==$revision)throw new \RuntimeException('Lampiran dikunci atau rekod berubah.');$field=null;foreach($r['fields'] as $f)if($f['key']===$key&&$f['type']==='file'&&Schema::visible($f,$r['values']))$field=$f;if(!$field||Database::query($p,'SELECT 1 FROM eforms_attachments WHERE submission_id=? AND field_key=?',[$id,$key])->fetchColumn())throw new \RuntimeException('Medan/lampiran tidak sah; satu fail setiap medan.');$doc=Documents::upload($p,$u,(int)$r['organisation_id'],'eforms',$field['label'],$file,null,$id);Database::query($p,'INSERT INTO eforms_attachments VALUES(?,?,?)',[$id,$key,$doc]);Database::query($p,'UPDATE eforms_submissions SET revision=revision+1 WHERE id=?',[$id]);self::event($p,$u,$id,(int)$r['organisation_id'],'attachment_uploaded','');return $doc;});}
 public static function delegate(\PDO $p,int $u,int $id,int $to,string $reason,int $revision):void {Core::tx($p,function()use($p,$u,$id,$to,$reason,$revision){$r=self::get($p,$u,$id,true);$step=$r['steps'][(int)$r['step_index']]??null;if($r['status']!=='submitted'||(int)$r['revision']!==$revision||!$step||(int)$step['user_id']!==$u)throw new \RuntimeException('Hanya penyemak semasa boleh delegate.');self::permit($p,$to,'submissions.review',(int)$r['organisation_id']);if($to===$u||$to===(int)$r['applicant_id'])throw new \RuntimeException('Delegation kepada diri/pemohon ditolak.');$reason=Core::text($reason,500);Database::query($p,'INSERT INTO eforms_delegations(submission_id,step_index,delegated_to,delegated_by,reason) VALUES(?,?,?,?,?)',[$id,$r['step_index'],$to,$u,$reason]);Database::query($p,'UPDATE eforms_submissions SET revision=revision+1 WHERE id=?',[$id]);self::event($p,$u,$id,(int)$r['organisation_id'],'delegated',$reason);$r['steps'][(int)$r['step_index']]['user_id']=$to;self::notify($p,$r,'submitted');});}
 public static function documentAccess(\PDO $p,int $u,array $doc,bool $manage):void {$id=Database::query($p,'SELECT submission_id FROM eforms_attachments WHERE document_id=?',[$doc['id']])->fetchColumn();if(!$id)throw new \RuntimeException('Dokumen tidak dipautkan.');$r=self::get($p,$u,(int)$id);if($manage)throw new \RuntimeException('Lampiran e-Forms immutable; tiada perubahan status dokumen.');if((int)$r['organisation_id']!==(int)$doc['organisation_id'])throw new \RuntimeException('Scope dokumen tidak sepadan.');}
 public static function pdf(\PDO $p,int $u,int $id):string {$r=self::get($p,$u,$id);$lines=[$r['title'],'Permohonan #'.$id.' · '.$r['status'],'Versi borang '.$r['version']];foreach($r['fields'] as $f)if(Schema::visible($f,$r['values'])&&$f['type']!=='section'){$v=$r['values'][$f['key']]??'';if(in_array($f['type'],['staff','organisation'],true)&&$v){$v=Database::query($p,$f['type']==='staff'?'SELECT full_name FROM staff_profiles WHERE staff_identity_id=?':'SELECT name FROM organisations WHERE id=?',[$v])->fetchColumn();}$lines[]=$f['label'].': '.(is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE):(string)$v);}foreach($r['files'] as $f)$lines[]='Lampiran '.$f['field_key'].' — Dokumen #'.$f['document_id'];$lines[]='Perakuan: '.$r['acknowledgement'];$lines[]='Diperakui pada: '.($r['acknowledged_at']??'Belum dihantar');foreach(Database::query($p,'SELECT h.action,h.reason,h.created_at FROM eforms_history h WHERE submission_id=? ORDER BY id',[$id])->fetchAll() as $h)$lines[]=$h['created_at'].' · '.$h['action'].' · '.$h['reason'];Audit::record($p,'eforms.pdf_exported',$u,(int)$r['organisation_id'],(string)$id,'eforms');return Pdf::generate($lines);}
}
